import{_ as a,o as e,c as n,a4 as l}from"./chunks/framework.CQGI5ZO3.js";const D=JSON.parse('{"title":"xs-setup(1)","description":"Clone the repository, build xs, install it, and make your first transfer.","frontmatter":{"title":"xs-setup(1)","description":"Clone the repository, build xs, install it, and make your first transfer.","manual":"xs-setup(1)","manualName":"Getting started","sectionNumber":"1"},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),t={name:"getting-started.md"};function o(p,s,c,i,r,d){return e(),n("div",null,[...s[0]||(s[0]=[l(`<h1 id="xs-setup-1" tabindex="-1">xs-setup(1) <a class="header-anchor" href="#xs-setup-1" aria-label="Permalink to &quot;xs-setup(1)&quot;">​</a></h1><div class="manual-deck"><strong>Getting started</strong><p>Clone the repository, build xs, install it, and make your first transfer.</p></div><h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME {#name}&quot;">​</a></h2><p><strong>xs-setup</strong> — get the xsync source from GitHub, build the <code>xs</code> executable, and install it.</p><p>The project is <a href="https://github.com/s4njee/xsyncv4">github.com/s4njee/xsyncv4</a>. Building takes a few minutes, mostly compiling the C++ sources. Every command on this page was run on a fresh clone.</p><h2 id="requirements" tabindex="-1">REQUIREMENTS <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;REQUIREMENTS {#requirements}&quot;">​</a></h2><p>Git, Python 3, a C++20 compiler (clang or gcc 12 or later), CMake 3.24 or later, Ninja, and the development files for zstd, xxHash and ICU. ICU supplies Unicode filename comparison.</p><aside class="manual-note"><span>CMAKE VERSION</span><p>Check with <code>cmake --version</code>. Debian 12 and Ubuntu 24.04 ship a new enough CMake; Ubuntu 22.04 ships 3.22, which is too old. There, install a current one with <code>python3 -m pip install --user cmake</code>, or from Kitware’s apt repository.</p></aside><div class="manual-table-wrap"><table><thead><tr><th scope="col">Platform</th><th scope="col">Dependencies</th></tr></thead><tbody><tr><td>macOS</td><td>Apple command-line developer tools, plus Homebrew packages</td></tr><tr><td>Debian / Ubuntu</td><td><code>build-essential</code> plus the packages below</td></tr><tr><td>Other Linux</td><td>The same tools and libraries from your distribution: a C++20 compiler, CMake, Ninja, and zstd, xxHash and ICU headers</td></tr></tbody></table></div><h2 id="dependencies" tabindex="-1">1 · INSTALL DEPENDENCIES <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;1 · INSTALL DEPENDENCIES {#dependencies}&quot;">​</a></h2><div class="example-caption">macOS</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xcode-select </span><span style="color:#DEDEDE;">--install</span><span style="color:#858585;">          # Apple command-line developer tools, if not installed</span></span>
<span class="line"><span style="color:#DEDEDE;">brew </span><span style="color:#DEDEDE;">install</span><span style="color:#DEDEDE;"> git</span><span style="color:#DEDEDE;"> cmake</span><span style="color:#DEDEDE;"> ninja</span><span style="color:#DEDEDE;"> zstd</span><span style="color:#DEDEDE;"> xxhash</span><span style="color:#DEDEDE;"> icu4c</span></span></code></pre></div><div class="example-caption">Debian / Ubuntu</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">sudo </span><span style="color:#DEDEDE;">apt</span><span style="color:#DEDEDE;"> update</span></span>
<span class="line"><span style="color:#DEDEDE;">sudo </span><span style="color:#DEDEDE;">apt</span><span style="color:#DEDEDE;"> install</span><span style="color:#DEDEDE;"> git</span><span style="color:#DEDEDE;"> build-essential</span><span style="color:#DEDEDE;"> cmake</span><span style="color:#DEDEDE;"> ninja-build</span><span style="color:#DEDEDE;"> python3</span><span style="color:#DEDEDE;"> libzstd-dev</span><span style="color:#DEDEDE;"> libxxhash-dev</span><span style="color:#DEDEDE;"> libicu-dev</span></span></code></pre></div><h2 id="clone" tabindex="-1">2 · CLONE THE REPOSITORY <a class="header-anchor" href="#clone" aria-label="Permalink to &quot;2 · CLONE THE REPOSITORY {#clone}&quot;">​</a></h2><div class="example-caption">Get the source</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">git </span><span style="color:#DEDEDE;">clone</span><span style="color:#DEDEDE;"> https://github.com/s4njee/xsyncv4.git</span></span>
<span class="line"><span style="color:#DEDEDE;">cd </span><span style="color:#DEDEDE;">xsyncv4</span></span></code></pre></div><p>Run the remaining commands from inside this <code>xsyncv4</code> directory. The repository is named <code>xsyncv4</code>; the program it builds is called <code>xs</code>.</p><h2 id="build" tabindex="-1">3 · BUILD <a class="header-anchor" href="#build" aria-label="Permalink to &quot;3 · BUILD {#build}&quot;">​</a></h2><div class="example-caption">Configure, compile, and check the result</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">-S</span><span style="color:#DEDEDE;"> .</span><span style="color:#DEDEDE;"> -B</span><span style="color:#DEDEDE;"> build</span><span style="color:#DEDEDE;"> -G</span><span style="color:#DEDEDE;"> Ninja</span></span>
<span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--build</span><span style="color:#DEDEDE;"> build</span></span>
<span class="line"><span style="color:#DEDEDE;">build/xs </span><span style="color:#DEDEDE;">--version</span></span></code></pre></div><p>The executable is <code>build/xs</code>. Its version line includes the Git revision it was built from, with <code>-dirty</code> if the sources were modified.</p><div class="example-caption">Optional: a quick self-test (prints “N checks, 0 failures”)</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--build</span><span style="color:#DEDEDE;"> build</span><span style="color:#DEDEDE;"> --target</span><span style="color:#DEDEDE;"> filter_test</span></span>
<span class="line"><span style="color:#DEDEDE;">build/filter_test</span></span></code></pre></div><h2 id="install" tabindex="-1">4 · INSTALL <a class="header-anchor" href="#install" aria-label="Permalink to &quot;4 · INSTALL {#install}&quot;">​</a></h2><div class="example-caption">Install into ~/.local</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--install</span><span style="color:#DEDEDE;"> build</span><span style="color:#DEDEDE;"> --prefix</span><span style="color:#DEDEDE;"> &quot;$HOME/.local&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">export PATH=</span><span style="color:#DEDEDE;">&quot;$HOME/.local/bin:$PATH&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">--version</span></span></code></pre></div><p>This installs <code>bin/xs</code>, the manpage (<code>man xs</code>) generated from its own help, and zsh completion. Add the <code>PATH</code> line to your shell configuration to keep it. To install for all users, use <code>sudo cmake --install build</code>, which installs under <code>/usr/local</code>.</p><div class="example-caption">zsh completion — put before your existing compinit setup</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">fpath=(</span><span style="color:#DEDEDE;">&quot;$HOME/.local/share/zsh/site-functions&quot;</span><span style="color:#DEDEDE;"> $fpath)</span></span>
<span class="line"><span style="color:#DEDEDE;">autoload </span><span style="color:#DEDEDE;">-Uz</span><span style="color:#DEDEDE;"> compinit</span></span>
<span class="line"><span style="color:#DEDEDE;">compinit</span></span></code></pre></div><h2 id="first-transfer" tabindex="-1">5 · FIRST TRANSFER <a class="header-anchor" href="#first-transfer" aria-label="Permalink to &quot;5 · FIRST TRANSFER {#first-transfer}&quot;">​</a></h2><div class="example-caption">Copy source contents into the destination</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>Replace both paths with your own. Progress is automatic when stderr is a terminal; <code>-P</code> also keeps partial data for a later retry. For remote transfers, the other machine needs <code>xs</code> too. See <a href="install.html#remote">remote install</a>, or let it <a href="compatibility.html#fallback">fall back to rsync</a>.</p><h2 id="updating" tabindex="-1">UPDATING <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;UPDATING {#updating}&quot;">​</a></h2><div class="example-caption">Pull the latest source and reinstall</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">cd </span><span style="color:#DEDEDE;">xsyncv4</span></span>
<span class="line"><span style="color:#DEDEDE;">git </span><span style="color:#DEDEDE;">pull</span></span>
<span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--build</span><span style="color:#DEDEDE;"> build</span></span>
<span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--install</span><span style="color:#DEDEDE;"> build</span><span style="color:#DEDEDE;"> --prefix</span><span style="color:#DEDEDE;"> &quot;$HOME/.local&quot;</span></span></code></pre></div><p><code>cmake --build</code> recompiles only what changed. If a build fails after a large update, start fresh with <code>rm -rf build</code> and repeat step 3.</p><h2 id="releases" tabindex="-1">RELEASE BUILDS <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;RELEASE BUILDS {#releases}&quot;">​</a></h2><div class="example-caption">Build static release binaries from the same checkout</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--preset</span><span style="color:#DEDEDE;"> release-static</span></span>
<span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--build</span><span style="color:#DEDEDE;"> --preset</span><span style="color:#DEDEDE;"> release-static</span></span></code></pre></div><p>The release flow produces Linux amd64/arm64 binaries and a macOS universal binary in <code>dist/</code>. It also needs Docker and GNU make. A macOS host is needed for the macOS output; a Linux host can build the Linux outputs. See <a href="install.html#releases">release binaries</a>.</p>`,42)])])}const u=a(t,[["render",o]]);export{D as __pageData,u as default};
